/** selectPrivateEntryFolderByUserId */
SELECT
    folder_id, folder_name, create_user_id, create_time, folder_type, resource_scope_user_id, resource_owner_id, access_policy, parent_folder_id, uuid, folder_name_path
FROM
    folder_tb

WHERE


            uuid = #{folderUuid}


            folder_id = #{folderId}


AND
    resource_scope_user_id = #{userId}
AND
    folder_type = #{folderType}
AND
    status = #{status}

/** selectPrivateEntryFolderByUserId */
SELECT
folder_id, folder_name, create_user_id, create_time, folder_type, resource_scope_user_id, resource_owner_id, access_policy, parent_folder_id, uuid, folder_name_path
FROM
folder_tb

    WHERE


