/** selectSimpleFolderOffsetById */
SELECT folder.uuid, folder.folder_name, folder.folder_type, folder.render_sequence,
      parent.uuid as parent_folder_uuid, folder.status
FROM folder_tb folder
LEFT JOIN folder_tb parent on folder.parent_folder_id = parent.folder_id
WHERE folder.parent_folder_id = #{parentFolderId}
AND folder.status = #{status}
ORDER BY folder.render_sequence ASC NULLS LAST, folder.folder_id ASC
OFFSET #{offset} LIMIT #{limit}

/** selectSimpleFolderOffsetByUuid */
SELECT folder.uuid, folder.folder_name, folder.folder_type, folder.render_sequence,
       parent.uuid as parent_folder_uuid, folder.status
FROM folder_tb folder
         LEFT JOIN folder_tb parent on folder.parent_folder_id = parent.folder_id
WHERE folder.parent_folder_id = (select folder_id from folder_tb where uuid = #{parentFolderUuid})
  AND folder.status = #{status}
ORDER BY folder.render_sequence ASC NULLS LAST, folder.folder_id ASC
OFFSET #{offset} LIMIT #{limit}

SELECT count(folder_id)
FROM folder_tb folder
WHERE parent_folder_id = #{parentFolderId}
  AND status = #{status}

SELECT folder.uuid, folder.folder_name, folder.folder_type, folder.render_sequence, parent.uuid AS parent_folder_uuid, folder.status FROM folder_tb folder LEFT JOIN folder_tb parent ON folder.parent_folder_id = parent.folder_id
CROSS JOIN ( SELECT folder_id, COALESCE(render_sequence, 2147483647) AS cursor_render_sequence FROM folder_tb WHERE uuid = #{lastFolderUuid} ) criteria
folder.parent_folder_id = #{parentFolderId} AND folder.status = #{status}
AND ( COALESCE(folder.render_sequence, 2147483647) > criteria.cursor_render_sequence OR ( COALESCE(folder.render_sequence, 2147483647) = criteria.cursor_render_sequence AND folder.folder_id > criteria.folder_id ) )
ORDER BY COALESCE(folder.render_sequence, 2147483647) ASC, folder.folder_id ASC LIMIT #{limit}

SELECT EXISTS (
    SELECT 1
    FROM folder_tb folder

    CROSS JOIN (
        SELECT
            folder_id,
            COALESCE(render_sequence, 2147483647) AS cursor_render_sequence
        FROM
            folder_tb
        WHERE
            uuid = #{lastFolderUuid}
    ) criteria


    folder.parent_folder_id = #{parentFolderId}
    AND folder.status = #{status}

        AND (
        COALESCE(folder.render_sequence, 2147483647) > criteria.cursor_render_sequence
        OR (
        COALESCE(folder.render_sequence, 2147483647) = criteria.cursor_render_sequence
        AND folder.folder_id > criteria.folder_id
        )
    )


LIMIT 1
)

